#include "RecentOperations.h"
#include <QTreeWidget>
#include <QLabel>
#include <QPushButton>
#include <QPointer>
#include <QVBoxLayout>
namespace putgd {
RecentOperations::RecentOperations(OperationService& operations,QWidget* parent):QWidget(parent),operations_(operations){setWindowTitle("put.gd — Recent activity");resize(850,450);auto* layout=new QVBoxLayout(this);tree_=new QTreeWidget(this);tree_->setObjectName("recentOperations");tree_->setHeaderLabels({"Action / item","ID / public URL","Operation / upload","Clipboard / local copy","Error"});layout->addWidget(tree_);status_=new QLabel(this);status_->setWordWrap(true);layout->addWidget(status_);auto* buttons=new QHBoxLayout;layout->addLayout(buttons);
 auto add=[this,buttons](const QString& label,const QString& name,auto fn){auto* button=new QPushButton(label,this);button->setObjectName(name);buttons->addWidget(button);connect(button,&QPushButton::clicked,this,[this,fn]{auto* row=tree_->currentItem();if(!row)return;while(row->parent())row=row->parent();const auto id=row->data(0,Qt::UserRole).toString();fn(id,[g=QPointer<RecentOperations>(this)](Error e,QJsonObject){if(g){g->status_->setText(e?e.code+": "+e.message:"Action accepted.");g->refresh();}});});};
 add("Copy result only","copyOperationResult",[this](auto id,auto reply){operations_.copyResult(id,reply);});add("Retry operation","retryOperation",[this](auto id,auto reply){operations_.retry(id,reply);});add("Retry local save only","retryLocalSave",[this](auto id,auto reply){operations_.retryLocalSave(id,reply);});add("Cancel","cancelOperation",[this](auto id,auto reply){operations_.cancel(id,reply);});connect(&operations_,&OperationService::changed,this,[this]{refresh();});connect(&operations_,&OperationService::initialized,this,[this]{refresh();});if(operations_.ready())refresh();}
void RecentOperations::refresh(){const auto sequence=++request_;if(loadInFlight_){loadPending_=true;return;}loadInFlight_=true;operations_.recent([g=QPointer<RecentOperations>(this),sequence](Error e,QJsonObject data){if(!g)return;g->loadInFlight_=false;if(g->loadPending_){g->loadPending_=false;g->refresh();return;}if(sequence!=g->request_)return;if(e){g->status_->setText(e.code+": "+e.message);return;}QString selected;if(auto* row=g->tree_->currentItem()){while(row->parent())row=row->parent();selected=row->data(0,Qt::UserRole).toString();}g->tree_->clear();for(auto value:data["operations"].toArray()){auto op=value.toObject();auto* row=new QTreeWidgetItem(g->tree_,{op["action"].toString(),op["id"].toString(),op["state"].toString(),op["copyStatus"].toString(),op["error"].toObject()["message"].toString()});row->setData(0,Qt::UserRole,op["id"].toString());for(auto itemValue:op["items"].toArray()){auto item=itemValue.toObject();auto local=item["local"].toObject();new QTreeWidgetItem(row,{item["artifact"].toObject()["name"].toString(),item["receipt"].toObject()["directUrl"].toString(),item["uploadStatus"].toString(),local["status"].toString()+" "+local["path"].toString(),item["error"].toObject()["message"].toString()+ (local["error"].toObject()["message"].toString().isEmpty()?QString{}:" Local save: "+local["error"].toObject()["message"].toString())+" Remote: "+item["remoteStatus"].toString()});}row->setExpanded(true);if(op["id"].toString()==selected)g->tree_->setCurrentItem(row);}});}
}
